+func TestEnv(t *testing.T) {
+	type Embed struct {
+		Flag string
+	}
+	type Cli struct {
+		One   Embed `prefix:"one-" embed:""`
+		Two   Embed `prefix:"two." embed:""`
+		Three Embed `prefix:"three_" embed:""`
+		Four  Embed `prefix:"four_" embed:""`
+		Five  bool
+		Six   bool `env:"-"`
+	}
+
+	var cli Cli
+
+	expected := Cli{
+		One:   Embed{Flag: "one"},
+		Two:   Embed{Flag: "two"},
+		Three: Embed{Flag: "three"},
+		Four:  Embed{Flag: "four"},
+		Five:  true,
+	}
+
+	// With the prefix
+	parser, unsetEnvs := newEnvParser(t, &cli, envMap{
+		"KONG_ONE_FLAG":   "one",
+		"KONG_TWO_FLAG":   "two",
+		"KONG_THREE_FLAG": "three",
+		"KONG_FOUR_FLAG":  "four",
+		"KONG_FIVE":       "true",
+		"KONG_SIX":        "true",
+	}, kong.DefaultEnvars("KONG"))
+	defer unsetEnvs()
+
+	_, err := parser.Parse(nil)
+	require.NoError(t, err)
+	require.Equal(t, expected, cli)
+
+	// Without the prefix
+	parser, unsetEnvs = newEnvParser(t, &cli, envMap{
+		"ONE_FLAG":   "one",
+		"TWO_FLAG":   "two",
+		"THREE_FLAG": "three",
+		"FOUR_FLAG":  "four",
+		"FIVE":       "true",
+		"SIX":        "true",
+	}, kong.DefaultEnvars(""))
+	defer unsetEnvs()
+
+	_, err = parser.Parse(nil)
+	require.NoError(t, err)
+	require.Equal(t, expected, cli)
+}
